import path from "node:path";
import type { PgDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";
import * as schema from "./schema";

/** Any Postgres-backed Drizzle database (postgres-js in the app, PGlite in tests). */
export type Db = PgDatabase<PgQueryResultHKT, typeof schema>;

/** SQL migrations generated by drizzle-kit (apps/api/drizzle). */
export const MIGRATIONS_DIR =
  process.env.MIGRATIONS_DIR ?? path.resolve(import.meta.dirname, "../../drizzle");

/** Connects and applies pending migrations, so the schema always matches the code. */
export async function connectDb(url: string): Promise<{ db: Db; close: () => Promise<void> }> {
  const sql = postgres(url, { max: 10, onnotice: () => {} });
  const db = drizzle(sql, { schema });
  await migrate(db, { migrationsFolder: MIGRATIONS_DIR });
  return { db: db as unknown as Db, close: () => sql.end() };
}
